1	{
2	  "$schema": "http://json-schema.org/draft-07/schema#",
3	  "title": "GroundTruthRecord",
4	  "description": "Unified ground-truth output for a single entity query",
5	  "type": "object",
6	  "properties": {
7	    "entity": {
8	      "type": "string",
9	      "description": "Entity name or domain queried"
10	    },
11	    "entity_type": {
12	      "type": "string",
13	      "enum": ["company", "person", "app", "domain"]
14	    },
15	    "geo": {
16	      "type": "string",
17	      "enum": ["vn", "global"]
18	    },
19	    "fetched_at": {
20	      "type": "string",
21	      "format": "date-time"
22	    },
23	    "registry": {
24	      "type": "object",
25	      "properties": {
26	        "mst": {"type": ["string", "null"]},
27	        "company_name": {"type": ["string", "null"]},
28	        "status": {"type": ["string", "null"]},
29	        "founding_date": {"type": ["string", "null"]},
30	        "headcount_bracket": {"type": ["string", "null"]},
31	        "source_url": {"type": ["string", "null"]},
32	        "zone": {"type": "string", "enum": ["[K]", "[T]", "[?]"]},
33	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
34	      }
35	    },
36	    "hiring": {
37	      "type": "object",
38	      "properties": {
39	        "active_jobs": {"type": ["integer", "null"]},
40	        "stack": {"type": "array", "items": {"type": "string"}},
41	        "salary_bracket": {"type": ["string", "null"]},
42	        "rating": {"type": ["number", "null"]},
43	        "review_count": {"type": ["integer", "null"]},
44	        "zone": {"type": "string", "enum": ["[K]", "[T]", "[?]"]},
45	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
46	      }
47	    },
48	    "app_store": {
49	      "type": "object",
50	      "properties": {
51	        "ios": {
52	          "type": ["object", "null"],
53	          "properties": {
54	            "rating": {"type": ["number", "null"]},
55	            "reviews": {"type": ["integer", "null"]},
56	            "iap": {"type": ["boolean", "null"]},
57	            "last_update": {"type": ["string", "null"]},
58	            "installs": {"type": ["string", "null"]}
59	          }
60	        },
61	        "android": {
62	          "type": ["object", "null"],
63	          "properties": {
64	            "rating": {"type": ["number", "null"]},
65	            "reviews": {"type": ["integer", "null"]},
66	            "installs": {"type": ["string", "null"]},
67	            "last_update": {"type": ["string", "null"]}
68	          }
69	        },
70	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
71	      }
72	    },
73	    "backlinks": {
74	      "type": "object",
75	      "properties": {
76	        "count": {"type": ["integer", "null"]},
77	        "top_referrers": {"type": "array", "items": {"type": "string"}},
78	        "zone": {"type": "string", "enum": ["[K]", "[T]", "[?]"]},
79	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
80	      }
81	    },
82	    "traffic": {
83	      "type": "object",
84	      "properties": {
85	        "monthly_visits": {"type": ["string", "null"]},
86	        "top_sources": {"type": "array", "items": {"type": "string"}},
87	        "zone": {"type": "string", "enum": ["[K]", "[T]", "[?]"]},
88	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
89	      }
90	    },
91	    "reverse_image": {
92	      "type": "object",
93	      "properties": {
94	        "matches": {"type": "array", "items": {"type": "object"}},
95	        "zone": {"type": "string", "enum": ["[K]", "[T]", "[?]"]},
96	        "source_status": {"type": "string", "enum": ["ok", "unavailable", "rate_limited", "parse_error"]}
97	      }
98	    },
99	    "triangulation_hints": {
100	      "type": "array",
101	      "items": {"type": "string"},
102	      "description": "Cross-source consistency checks and anomaly flags"
103	    }
104	  },
105	  "required": ["entity", "entity_type", "fetched_at"]
106	}
